import { ref, type Ref } from 'vue';
import QRCode from 'qrcode';
import { useEngineStore } from '~/stores/engine-store';

/**
 * Prepares (and caches) the public share link + QR code for a project's patch
 * table. Call `prepare()` early (e.g. when the table view opens) so the QR is
 * already generated by the time the user opens the share overlay.
 */
export function useSharePatch(projectId: Ref<string>) {
  const engineStore = useEngineStore();
  const supabase = useSupabaseClient();

  const loading = ref(false);
  const error = ref('');
  const shareUrl = ref('');
  const qrDataUrl = ref('');
  let prepared = false;

  /** Fetch the project's share token, generating + persisting one if absent. */
  async function ensureShareToken(): Promise<string> {
    const { data, error: selErr } = await supabase
      .from('projects')
      .select('public_share_token')
      .eq('id', projectId.value)
      .single();
    if (selErr) throw selErr;

    let token = (data as { public_share_token: string | null })?.public_share_token;
    if (!token) {
      token = crypto.randomUUID();
      const { error: updErr } = await supabase
        .from('projects')
        .update({ public_share_token: token })
        .eq('id', projectId.value);
      if (updErr) throw updErr;
    }
    return token;
  }

  async function prepare(force = false) {
    if (loading.value) return;
    if (prepared && !force) return;
    if (!projectId.value) return;
    loading.value = true;
    error.value = '';
    try {
      // Persist current state so the public page reflects the latest patch.
      await engineStore.saveSnapshotNow();
      const token = await ensureShareToken();
      shareUrl.value = `${window.location.origin}/share/${token}`;
      qrDataUrl.value = await QRCode.toDataURL(shareUrl.value, {
        width: 320,
        margin: 1,
        errorCorrectionLevel: 'M',
      });
      prepared = true;
    } catch (err) {
      console.error('[share] prepare failed:', err);
      error.value = 'Share-Link konnte nicht erstellt werden.';
    } finally {
      loading.value = false;
    }
  }

  return {
    loading,
    error,
    shareUrl,
    qrDataUrl,
    prepare,
    refresh: () => prepare(true),
  };
}
